// Builds the signed envelope for Collect (mail.received). Field names differ between trigger
// nodes (IMAP / Gmail / Outlook) — adjust the right-hand sides if your node uses others.
const crypto = require('crypto');
const secret = $env.COLLECT_SIGNING_SECRET;
return $input.all().map((item) => {
  const m = item.json;
  const headers = m.headers || {};
  const messageId = m.messageId || headers['message-id'] || m.id;
  const refs = (m.references || headers['references'] || '').toString().split(/\s+/).filter(Boolean);
  const envelope = {
    id: messageId,
    type: 'mail.received',
    occurredAt: new Date(m.date || Date.now()).toISOString(),
    data: {
      messageId,
      from: (m.from && (m.from.value ? m.from.value[0].address : m.from)) || '',
      subject: m.subject || '',
      text: m.text || m.textPlain || '',
      html: m.html || m.textHtml || undefined,
      inReplyTo: m.inReplyTo || headers['in-reply-to'] || undefined,
      references: refs,
      attachments: (m.attachments || []).map((a) => ({
        filename: a.filename || a.fileName || 'attachment',
        contentType: a.contentType || a.mimeType || 'application/octet-stream',
        size: a.size || 0,
      })),
    },
  };
  const raw = JSON.stringify(envelope);
  const t = Math.floor(Date.now() / 1000);
  const v1 = crypto.createHmac('sha256', secret).update(`${t}.${raw}`).digest('hex');
  return { json: { raw, signature: `t=${t},v1=${v1}` } };
});
